parts.text:
{
  "extractions": [
    {
      "unit": "F002",
      "unit_attributes": {
        "statement": "No person may operate a civil aircraft of U.S. registry at cabin pressure altitudes above 12,500 feet (MSL) up to and including 14,000 feet (MSL) unless the required minimum flight crew is provided with and uses supplemental oxygen for that part of the flight at those altitudes that is of more than 30 minutes duration.",
        "kind": "prohibition",
        "modality": "must_not",
        "scope_text": "When operating a civil aircraft of U.S. registry at cabin pressure altitudes above 12,500 feet (MSL) up to and including 14,000 feet (MSL).",
        "scope_quotes": [
          "F001"
        ],
        "modality_quote": "No person may",
        "references": null
      }
    },
    {
      "unit": "F003",
      "unit_attributes": {
        "statement": "No person may operate a civil aircraft of U.S. registry at cabin pressure altitudes above 14,000 feet (MSL) unless the required minimum flight crew is provided with and uses supplemental oxygen during the entire flight time at those altitudes.",
        "kind": "prohibition",
        "modality": "must_not",
        "scope_text": "When operating a civil aircraft of U.S. registry at cabin pressure altitudes above 14,000 feet (MSL).",
        "scope_quotes": [
          "F001"
        ],
        "modality_quote": "No person may",
        "references": null
      }
    },
    {
      "unit": "F004",
      "unit_attributes": {
        "statement": "No person may operate a civil aircraft of U.S. registry at cabin pressure altitudes above 15,000 feet (MSL) unless each occupant of the aircraft is provided with supplemental oxygen.",
        "kind": "prohibition",
        "modality": "must_not",
        "scope_text": "When operating a civil aircraft of U.S. registry at cabin pressure altitudes above 15,000 feet (MSL).",
        "scope_quotes": [
          "F001"
        ],
        "modality_quote": "No person may",
        "references": null
      }
    },
    {
      "unit": "F006",
      "unit_attributes": {
        "statement": "No person may operate a civil aircraft of U.S. registry with a pressurized cabin at flight altitudes above flight level 250 unless at least a 10-minute supply of supplemental oxygen, in addition to any oxygen required to satisfy paragraph (a) of § 91.211, is available for each occupant of the aircraft for use in the event that a descent is necessitated by loss of cabin pressurization.",
        "kind": "prohibition",
        "modality": "must_not",
        "scope_text": "When operating a civil aircraft of U.S. registry with a pressurized cabin at flight altitudes above flight level 250.",
        "scope_quotes": [
          "F005"
        ],
        "modality_quote": "No person may",
        "references": [
          "paragraph (a)"
        ]
      }
    },
    {
      "unit": "F007",
      "unit_attributes": {
        "statement": "No person may operate a civil aircraft of U.S. registry with a pressurized cabin at flight altitudes above flight level 350 unless one pilot at the controls of the airplane is wearing and using an oxygen mask that is secured and sealed and that either supplies oxygen at all times or automatically supplies oxygen whenever the cabin pressure altitude of the airplane exceeds 14,000 feet (MSL), except that the one pilot need not wear and use an oxygen mask while at or below flight level 410 if there are two pilots at the controls and each pilot has a quick-donning type of oxygen mask that can be placed on the face with one hand from the ready position within 5 seconds, supplying oxygen and properly secured and sealed.",
        "kind": "prohibition",
        "modality": "must_not",
        "scope_text": "When operating a civil aircraft of U.S. registry with a pressurized cabin at flight altitudes above flight level 350.",
        "scope_quotes": [
          "F005"
        ],
        "modality_quote": "No person may",
        "references": null
      }
    },
    {
      "unit": "F007",
      "unit_attributes": {
        "statement": "When operating a civil aircraft of U.S. registry with a pressurized cabin at flight altitudes above flight level 350, the one pilot at the controls need not wear and use an oxygen mask while at or below flight level 410 if there are two pilots at the controls and each pilot has a quick-donning type of oxygen mask that can be placed on the face with one hand from the ready position within 5 seconds, supplying oxygen and properly secured and sealed.",
        "kind": "exemption",
        "modality": "not_required",
        "scope_text": "Operating a civil aircraft of U.S. registry with a pressurized cabin at flight altitudes above flight level 350 up to and including flight level 410, with two pilots at the controls and each having a qualifying quick-donning mask.",
        "scope_quotes": [
          "F005",
          "F007"
        ],
        "modality_quote": "need not",
        "references": null
      }
    },
    {
      "unit": "F008",
      "unit_attributes": {
        "statement": "Notwithstanding paragraph (b)(1)(ii) of § 91.211, if for any reason at any time it is necessary for one pilot to leave the controls of the aircraft when operating at flight altitudes above flight level 350, the remaining pilot at the controls shall put on and use an oxygen mask until the other pilot has returned to that crewmember's station.",
        "kind": "requirement",
        "modality": "must",
        "scope_text": "When operating at flight altitudes above flight level 350, if for any reason at any time it is necessary for one pilot to leave the controls of the aircraft.",
        "scope_quotes": [
          "F008"
        ],
        "modality_quote": "shall",
        "references": [
          "paragraph (b)(1)(ii)"
        ]
      }
    }
  ]
}
